// Some portions generated by Codex

const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const http = require('node:http');
const path = require('node:path');
const ts = require('typescript');
const ROOT = path.resolve(__dirname, '../..');
const SOURCE = path.join(ROOT, 'tools/workbench/src/main/frontend/graph-explorer');

/** Serve the real renderer without a backend, generated assets or a second build writing shared caches. */
function rendererModules() {
	const modules = new Map();
	const pending = ['graph-canvas-controller.ts'];
	while (pending.length) {
		const name = pending.pop();
		if (modules.has(name.replace(/\.ts$/, '.js'))) continue;
		const output = ts.transpileModule(fs.readFileSync(path.join(SOURCE, name), 'utf8'), {
			compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 }
		}).outputText;
		const code = output.replace(/from "\.\/([^"/]+)\.ts"/g, (_match, dependency) => {
			pending.push(`${dependency}.ts`);
			return `from "./${dependency}.js"`;
		});
		modules.set(name.replace(/\.ts$/, '.js'), code);
	}
	return modules;
}

const FIXTURE = `<!doctype html><html><head><meta charset="utf-8">
<link rel="stylesheet" href="/workbench-refresh.css"><link rel="stylesheet" href="/graph-explorer.css">
<style>html,body{margin:0}.graph-explorer{position:relative;width:1280px;height:780px;padding:0;border:0}
canvas{position:absolute;inset:0;width:100%;height:100%}</style></head><body>
<div class="graph-explorer"><canvas id="base"></canvas><canvas id="overlay"></canvas></div>
<button id="focus">Highlight first node</button><button id="clear">Clear highlight</button>
<script type="module">
import { CanvasGraph, colorToRgba, readCanvasPalette } from '/renderer/graph-canvas-controller.js';
const parameters = new URLSearchParams(location.search);
document.documentElement.dataset.theme = parameters.get('theme');
const count = Number(parameters.get('nodes'));
const nodes = Array.from({length:count}, (_,i) => ({id:'urn:n:'+i,label:'Node '+i,kind:'iri',types:[],
  x:i===0?100:i===1?1180:100+((i-2)%30)*36,y:i<2?60:180+Math.floor((i-2)/30)*18}));
const edges = Array.from({length:count-1}, (_,i) => ({id:'e'+i,source:nodes[i].id,target:nodes[i+1].id,
  predicate:'urn:link',label:'link'}));
const props = {graph:{nodes,edges,revision:1},transform:{x:0,y:0,k:1},selected:new Set(),focused:null,
  showLabels:false,groups:[],onTransform:t=>{props.transform=t},onPositions:()=>{},onSelect:()=>{},
  onBoxSelect:()=>{},onMenu:()=>{},onInterrupt:()=>{},onDragStart:()=>{}};
const base = document.querySelector('#base'), overlay = document.querySelector('#overlay');
const view = new CanvasGraph(base,overlay,()=>props);
const gl = base.getContext('webgl'), ctx = overlay.getContext('2d');
document.querySelector('#focus').onclick = () => {props.focused=nodes[0].id;view.update()};
document.querySelector('#clear').onclick = () => {props.focused=null;view.update()};
const groups = data => Array.from({length:data.length/4}, (_,i) => [...data.slice(i*4,i*4+4)]);
window.captureGraphFrame = zoom => {
  props.transform={x:640*(1-zoom),y:60*(1-zoom),k:zoom};view.update();
  // Read after the scheduled draw and before the browser discards its non-preserved drawing buffer.
  return new Promise(resolve=>requestAnimationFrame(()=>{
    const scale=base.width/base.getBoundingClientRect().width;
    const x=Math.round(638*scale),y=Math.round(58*scale),side=Math.round(4*scale);
    const pixels=new Uint8Array(side*side*4);
    gl.readPixels(x,base.height-y-side,side,side,gl.RGBA,gl.UNSIGNED_BYTE,pixels);
    resolve({renderer:overlay.dataset.renderer,nodes:nodes.length,edges:edges.length,pixels:groups(pixels),
      overlay:groups(ctx.getImageData(x,y,side,side).data),error:gl.getError(),
      color:colorToRgba(ctx,readCanvasPalette(overlay).edge,[0,0,0,1])});
  }));
};
</script></body></html>`;

let server;
let origin;
test.beforeAll(async () => {
	const modules = rendererModules();
	server = http.createServer((request, response) => {
		const url = new URL(request.url, 'http://127.0.0.1');
		const module = modules.get(url.pathname.replace(/^\/renderer\//, ''));
		if (module) {
			response.setHeader('Content-Type', 'application/javascript');
			return response.end(module);
		}
		const css = url.pathname === '/graph-explorer.css' ? path.join(SOURCE, 'graph-explorer.css')
			: url.pathname === '/workbench-refresh.css'
				? path.join(ROOT, 'tools/workbench/src/main/frontend/static/styles/workbench-refresh.css') : null;
		if (css) {
			response.setHeader('Content-Type', 'text/css');
			return response.end(fs.readFileSync(css));
		}
		response.setHeader('Content-Type', 'text/html');
		response.end(FIXTURE);
	});
	await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
	origin = `http://127.0.0.1:${server.address().port}`;
});
test.afterAll(async () => {
	if (server) await new Promise(resolve => server.close(resolve));
});

for (const theme of ['light', 'dark']) {
	for (const nodes of [500, 1000]) {
		test(`ordinary graph edges remain visible (${theme}, ${nodes} nodes)`, async ({ page }) => {
			await page.setViewportSize({ width: 1280, height: 850 });
			await page.emulateMedia({ reducedMotion: 'reduce' });
			await page.goto(`${origin}/?theme=${theme}&nodes=${nodes}`);
			await page.waitForFunction(() => {
				const canvas = document.querySelector('#base');
				return window.captureGraphFrame && canvas.width === Math.round(
					canvas.getBoundingClientRect().width * Math.min(2, window.devicePixelRatio || 1));
			});
			const verify = async zoom => {
				const frame = await page.evaluate(value => window.captureGraphFrame(value), zoom);
				expect(frame.renderer).toBe('webgl');
				expect(frame.nodes).toBe(nodes);
				expect(frame.edges).toBe(nodes - 1);
				expect(frame.error).toBe(0);
				const pixel = frame.pixels.find(value => Math.abs(value[3] - 255 * 0.26) <= 1);
				expect(pixel, 'ordinary edges retain source opacity in the composited canvas').toBeTruthy();
				for (let channel = 0; channel < 3; channel++) {
					expect(Math.abs(pixel[channel] - 255 * frame.color[channel] * 0.26)).toBeLessThanOrEqual(1);
					expect(pixel[channel]).toBeLessThanOrEqual(pixel[3] + 1);
				}
				return frame;
			};
			for (const zoom of [0.04, 0.16, 1, 4]) await verify(zoom);
			await page.locator('#focus').click();
			expect((await verify(1)).overlay.some(pixel => pixel[3] > 0)).toBe(true);
			await page.locator('#clear').click();
			expect((await verify(1)).overlay.every(pixel => pixel[3] === 0)).toBe(true);
		});
	}
}
